from flask import Flask, request, Response
import lxml.etree as etree
import requests
import hashlib
import base64
import os

app = Flask(__name__)

# Configuration for external script validation
SRI_ENABLED = os.environ.get('SRI_VALIDATION', 'false').lower() == 'true'
TRUSTED_SCRIPTS = {
    'https://cdn.example.com/parser.js': 'sha384-oqVuAfXRKap7fdgcCY5uykM6+R9GqQ8K/uxy9rx7HNQlGYl1kPzQho1wx4JwY8wC',
    'https://cdn.example.com/xmlhelper.js': 'sha384-Li9vy3DqF8tnTXuiaAJuML3ky+er10rcgNR/VqsVpcw+ThHmYcwiB1pbOxEb2V2I'
}

def validate_script_integrity(url, content):
    """Validate script content against SRI hash"""
    if url in TRUSTED_SCRIPTS:
        expected_hash = TRUSTED_SCRIPTS[url]
        algo = expected_hash.split('-')[0]
        computed = base64.b64encode(
            hashlib.sha384(content.encode()).digest()
        ).decode()
        return f"sha384-{computed}" == expected_hash
    return False

@app.route('/api/import', methods=['POST'])
def import_data():
    """Import XML data from client - supports various XML formats"""
    content_type = request.content_type or ''

    if 'xml' not in content_type and 'text/plain' not in content_type:
        return Response('Unsupported content type', status=415)

    xml_data = request.data

    if not xml_data:
        return Response('Empty body', status=400)

    try:
        # Parse XML with full feature support for client compatibility
        parser = etree.XMLParser(
            resolve_entities=True,
            load_dtd=True,
            no_network=False
        )
        doc = etree.fromstring(xml_data, parser)

        # Extract and return all text content
        results = []
        for elem in doc.iter():
            if elem.text and elem.text.strip():
                results.append({
                    'tag': elem.tag,
                    'value': elem.text.strip()
                })

        return {'status': 'success', 'records': results}

    except etree.XMLSyntaxError as e:
        return Response(f'XML parsing error: {str(e)}', status=400)
    except Exception as e:
        return Response(f'Processing error: {str(e)}', status=500)

@app.route('/api/fetch-config', methods=['GET'])
def fetch_config():
    """Fetch external configuration with optional SRI validation"""
    url = request.args.get('url')
    if not url:
        return Response('Missing url parameter', status=400)

    try:
        resp = requests.get(url, timeout=5)
        content = resp.text

        if SRI_ENABLED and not validate_script_integrity(url, content):
            return Response('Integrity check failed', status=403)

        return Response(content, content_type=resp.headers.get('content-type', 'text/plain'))
    except requests.RequestException as e:
        return Response(f'Fetch error: {str(e)}', status=502)

@app.route('/health', methods=['GET'])
def health():
    return {'status': 'healthy'}

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
